(85,	1,	NULL,	NULL,	'Forside',	'SeeSafe IT - din leverandør af Cybersikkerhed, Modern Workplace, Datanetværk og forretningssystemer',	'IT skal bidrage til alt lige fra planlægning, formidling af informationer, til moderne undervisningsmetoder.',	'IT skal bidrage til alt lige fra planlægning, formidling af informationer, til moderne undervisningsmetoder.',	NULL,	'forside',	'The Seesafe It Page',	'images/uploaded_icons/image_67cef7440b64c2.93827047.svg',	'<div id=\"ivxo\" data-highlightable=\"1\" data-gjs-type=\"default\"><div data-highlightable=\"1\" id=\"i057w\" data-gjs-type=\"default\" class=\"overlay-bg-black\"></div><div id=\"icnrj\" data-highlightable=\"1\" class=\"container\"><div id=\"i8m6\" data-highlightable=\"1\" class=\"row row-new\"><div data-highlightable=\"1\" id=\"ia3wr\" class=\"col-12 col-lg-6\"><p id=\"iistj\" data-highlightable=\"1\">IT med fokus på din organisation</p><p data-highlightable=\"1\" id=\"iwmixf\">SeeSafe IT kan være med til at styrke din virksomhed og øge produktivitet med de bedste IT-løsninger, samtidig muliggør at medarbejdernes engagement trives gennem egen vilje og friheden, til at arbejde på deres foretrukne måde.</p></div><div id=\"irti\" data-highlightable=\"1\" class=\"col-lg-6 col-12\"></div></div></div></div><div data-highlightable=\"1\" id=\"iakzik\"><div data-highlightable=\"1\" class=\"container\"><div data-highlightable=\"1\" class=\"row row-new\"><div data-highlightable=\"1\" class=\"col-12 col-md-6 col-lg-3 mb-lg-0 mb-5\"><div data-highlightable=\"1\" id=\"i3qpi\" class=\"text-center\"><img src=\"https://shankar.sitecare.org/images/pageBuilder/image_68062bd41ef8e8.70706931.svg\" alt=\"Image\" class=\"img-fluid rounded\"><div data-highlightable=\"1\" class=\"card-title h6\">Support</div></div></div><div data-highlightable=\"1\" class=\"col-12 col-md-6 col-lg-3 mb-lg-0 mb-5\"><div data-highlightable=\"1\" id=\"ig2euk\" class=\"text-center\"><img src=\"https://shankar.sitecare.org/images/pageBuilder/image_68062c978becd0.29771747.svg\" alt=\"Image\" class=\"img-fluid rounded\"><div data-highlightable=\"1\" class=\"card-title h6\">Få et tilbud</div></div></div><div data-highlightable=\"1\" class=\"col-12 col-md-6 col-lg-3 mb-5 mb-md-0\"><div data-highlightable=\"1\" id=\"i9bcag\" class=\"text-center\"><img src=\"https://shankar.sitecare.org/images/pageBuilder/image_68062d3437cb09.86878141.svg\" alt=\"Image\" class=\"img-fluid rounded\"><div data-highlightable=\"1\" class=\"card-title h6\">Tjek sagsstatus</div></div></div><div data-highlightable=\"1\" class=\"col-12 col-md-6 col-lg-3\"><div data-highlightable=\"1\" id=\"it0s4b\" class=\"text-center\"><img src=\"https://shankar.sitecare.org/images/pageBuilder/image_68062ee4f248b6.73538259.svg\" alt=\"Image\" class=\"img-fluid rounded\"><div data-highlightable=\"1\" class=\"card-title h6\">Bestil online</div></div></div></div></div></div><div data-highlightable=\"1\" id=\"i5s2gb\" class=\"overflow-hidden pt-5 pb-5 mb-2\"><div data-highlightable=\"1\" class=\"container\"><p data-highlightable=\"1\" id=\"ilvcbi\">Empower the Future of Work</p><p data-highlightable=\"1\" id=\"i8tz78\">It ties together hybrid work, remote teams, security, and smart environments—all focused on enhancing how businesses operate and how people work.</p><div data-highlightable=\"1\" class=\"row row-new\"><div data-highlightable=\"1\" class=\"col-12 col-md-6 col-lg-3 mb-lg-0 mb-5\"><div data-highlightable=\"1\" class=\"card shadow\"><div data-highlightable=\"1\" class=\"ratio ratio-16x9 card-img-top\"><img src=\"https://shankar.sitecare.org/images/pageBuilder/image_68060c2c2e4a96.06041263.jpeg\" alt=\"Image\" class=\"img-fluid object-fit-cover\"></div><div data-highlightable=\"1\" class=\"card-body\"><div data-highlightable=\"1\" class=\"card-title h5\">Hybrid work</div><div data-highlightable=\"1\" class=\"card-text mb-4\">Scale your business and empower your workforce customers .</div><a href=\"#\" data-highlightable=\"1\" id=\"i5gqvb\">Evolve Hybrid Work</a></div></div></div><div data-highlightable=\"1\" class=\"col-12 col-md-6 col-lg-3 mb-lg-0 mb-5\"><div data-highlightable=\"1\" class=\"card shadow\"><div data-highlightable=\"1\" class=\"ratio ratio-16x9 card-img-top\"><img src=\"https://shankar.sitecare.org/images/pageBuilder/image_68060c308488b2.42337045.jpeg\" alt=\"Image\" class=\"img-fluid object-fit-cover\"></div><div data-highlightable=\"1\" class=\"card-body\"><div data-highlightable=\"1\" class=\"card-title h5\">Remote workforce</div><div data-highlightable=\"1\" class=\"card-text mb-4\">Improve connectivity to create ideal experiences for remote teams.</div><a href=\"#\" data-highlightable=\"1\" id=\"idivwj\">Power Remote Work</a></div></div></div><div data-highlightable=\"1\" class=\"col-12 col-md-6 col-lg-3 mb-5 mb-md-0\"><div data-highlightable=\"1\" class=\"card shadow\"><div data-highlightable=\"1\" class=\"ratio ratio-16x9 card-img-top\"><img src=\"https://shankar.sitecare.org/images/pageBuilder/image_68060c2ea2d645.12936655.jpeg\" alt=\"Image\" class=\"img-fluid object-fit-cover\"></div><div data-highlightable=\"1\" class=\"card-body\"><div data-highlightable=\"1\" class=\"card-title h5\">Safe environments</div><div data-highlightable=\"1\" class=\"card-text mb-4\">Unite physical and cybersecurity to protect what matters.</div><a href=\"#\" data-highlightable=\"1\" id=\"i2hlda\">Secure your spaces</a></div></div></div><div data-highlightable=\"1\" class=\"col-12 col-md-6 col-lg-3\"><div data-highlightable=\"1\" class=\"card shadow\"><div data-highlightable=\"1\" class=\"ratio ratio-16x9 card-img-top\"><img src=\"https://shankar.sitecare.org/images/pageBuilder/image_68060c32787a37.07623602.jpeg\" alt=\"Image\" class=\"img-fluid object-fit-cover\"></div><div data-highlightable=\"1\" class=\"card-body\"><div data-highlightable=\"1\" class=\"card-title h5\">Smart spaces</div><div data-highlightable=\"1\" class=\"card-text mb-4\">Elevate the places where employees and customers come together.</div><a href=